"use client";

import { useState } from "react";
import { Search } from "lucide-react";
import { ASSET_TYPE_LABEL, type AssetType } from "@/lib/market/assets";
import { market } from "@/lib/market/provider";
import { useNow } from "@/lib/ui/clock";
import { AssetRow } from "../asset-row";
import { Card, EmptyState } from "../ui";

type Filter = "all" | AssetType;
type Sort = "name" | "gainers" | "losers";

export function MarketsScreen() {
  const now = useNow();
  const [query, setQuery] = useState("");
  const [filter, setFilter] = useState<Filter>("all");
  const [sort, setSort] = useState<Sort>("name");

  const q = query.trim().toLowerCase();
  const assets = market
    .listAssets()
    .filter((a) => filter === "all" || a.type === filter)
    .filter((a) => !q || a.name.toLowerCase().includes(q) || a.symbol.toLowerCase().includes(q) || a.sector.toLowerCase().includes(q))
    .map((a) => ({ a, chg: market.quote(a.symbol, now).changePct }))
    .sort((x, y) =>
      sort === "gainers" ? y.chg - x.chg : sort === "losers" ? x.chg - y.chg : x.a.name.localeCompare(y.a.name),
    );

  return (
    <div className="flex flex-col gap-5">
      <h1 className="text-3xl font-semibold tracking-tight">Invest</h1>

      <label className="flex items-center gap-3 rounded-2xl border border-line bg-surface px-4 py-3 focus-within:border-accent">
        <Search size={18} className="text-muted" />
        <input
          value={query}
          onChange={(e) => setQuery(e.target.value)}
          placeholder="Search stocks, ETFs, crypto"
          className="w-full bg-transparent text-[15px] outline-none placeholder:text-muted"
        />
      </label>

      <div className="scrollbar-none -mx-4 flex gap-2 overflow-x-auto px-4">
        {(["all", "stock", "etf", "crypto"] as const).map((f) => (
          <Chip key={f} active={filter === f} onClick={() => setFilter(f)}>
            {f === "all" ? "All" : ASSET_TYPE_LABEL[f]}
          </Chip>
        ))}
        <span className="mx-1 w-px shrink-0 bg-line" />
        {(
          [
            ["name", "A–Z"],
            ["gainers", "Top gainers"],
            ["losers", "Top losers"],
          ] as const
        ).map(([s, label]) => (
          <Chip key={s} active={sort === s} onClick={() => setSort(s)}>
            {label}
          </Chip>
        ))}
      </div>

      <Card className="p-1.5">
        {assets.length === 0 ? (
          <EmptyState title="Nothing found" body={`No assets match “${query}”.`} />
        ) : (
          assets.map(({ a }) => <AssetRow key={a.symbol} symbol={a.symbol} now={now} subtitle={`${a.symbol} · ${a.sector}`} />)
        )}
      </Card>
    </div>
  );
}

function Chip({ active, onClick, children }: { active: boolean; onClick: () => void; children: React.ReactNode }) {
  return (
    <button
      onClick={onClick}
      className={`shrink-0 rounded-full px-4 py-2 text-sm font-semibold transition ${
        active ? "bg-fg text-bg" : "bg-surface text-muted hover:text-fg"
      }`}
    >
      {children}
    </button>
  );
}
